            "E17bd6f60d466f9f9:0:697",
            "E17bd6f60d466f9f9:697:1390"
          ],
          "condicoes": [
            "aplica-se ao contexto das vulnerabilidades citadas pela CISA na pilha Treck TCP/IP",
            "o texto descreve possibilidade de exploração remota, não ocorrência confirmada em toda instalação"
          ],
          "limites": [
            "é um alerta de segurança com recomendações, não uma norma",
            "a jurisdição informada é dos EUA",
            "não define procedimento completo de contenção, erradicação e recuperação"
          ]
        },
        {
          "proposicao": "Como medidas de mitigação e redução de exposição, recomenda-se monitorar alertas correntes e futuros da CISA, avaliar exposição potencial, obter patches e estratégias de remediação com fornecedores e atualizar para versão estável mais recente da pilha afetada quando disponível.",
          "trechos": [
            "E17bd6f60d466f9f9:0:697",
            "E17bd6f60d466f9f9:697:1390"
          ],
          "condicoes": [
            "quando os dispositivos ou sistemas utilizarem implementações afetadas da Treck TCP/IP stack",
            "quando houver patches e remediações disponibilizados por fornecedores"
          ],
          "limites": [
            "não informa critérios de teste prévio em ambiente crítico",
            "não informa janela operacional, priorização por criticidade nem compatibilidade por fabricante"
          ]
        },
        {
          "proposicao": "Para detecção e contenção, o alerta recomenda minimizar a exposição de rede dos sistemas de controle, evitar acessibilidade direta pela internet, isolar redes de controle e dispositivos remotos atrás de firewalls e da rede de negócios, usar métodos seguros para acesso remoto e reportar atividade maliciosa suspeita segundo procedimentos internos e à CISA para rastreamento e correlação.",
          "trechos": [
            "E17bd6f60d466f9f9:1390:2083",
            "E17bd6f60d466f9f9:2083:2399"
          ],
          "condicoes": [
            "quando houver acesso remoto necessário",
            "o reporte externo mencionado é à CISA, conforme o contexto do alerta"
          ],
          "limites": [
            "o texto não detalha coleta de logs, correlação local, preservação de evidências ou fluxo interno com emergência operacional",
            "a recomendação de reporte externo é contextual ao ecossistema institucional citado e não deve ser convertida em requisito brasileiro"
          ]
        }
      ]
